WITH valid AS (SELECT id, customer_id, device, browser, started_at, INITCAP(TRIM(device)) device_title FROM sessions WHERE started_at > DATE '2023-08-01' AND country IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM valid), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT session_id, CASE WHEN session_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS session_id_tier, MIN(session_id) AS min_session_id, PERCENTILE_APPROX(is_new_burst, ARRAY(0.25, 0.5, 0.75)) AS is_new_burst_quartiles, SUM(CASE WHEN browser = 'Firefox' THEN is_new_burst ELSE 0 END) AS firefox_is_new_burst, GROUPING(session_id) AS grouping_id FROM sessionized GROUP BY GROUPING SETS ((session_id, CASE WHEN session_id >= 8 THEN 'LARGE' ELSE 'SMALL' END), (session_id)) HAVING SUM(CASE WHEN browser = 'Firefox' THEN is_new_burst ELSE 0 END) > 0 ORDER BY session_id;
